import React, { useState } from 'react';
import axios from 'axios';
import './Contact.css';
import PageTitle from '../PageTitle';

function Contact() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [subject, setSubject] = useState('');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Formdaki verileri backend'e gönder
    if (!name || !email || !subject || !message) {
      setError('Tüm alanları doldurduğunuzdan emin olun.');
      return;
    }

    try {
      const response = await axios.post('http://localhost:3001/api/notifications', {
        name,
        email,
        subject,
        message,
      });
      setSuccess(response.data.message);
      setName('');
      setEmail('');
      setSubject('');
      setMessage('');
    } catch (error) {
      setError('Mesaj gönderilirken bir hata oluştu.');
    }
  };

  return (
    <>
      <PageTitle title="İletişim" />
      <div className="contact-page">
        <div className="contact-info-container">
          <div className="contact-info-left">
            <h2>Şirket Bilgileri</h2>
            <p><strong>Şirket İsmi:</strong> Beehive Inc.</p>
            <p><strong>Adres:</strong> 123 Bee Street, Honey City</p>
            <p><strong>Telefon:</strong> +90 123 456 7890</p>
          </div>
          <div className="contact-info-right">
            <h2>İletişim Formu</h2>
            <form onSubmit={handleSubmit}>
              <label>
                İsim:
                <input type="text" name="name" value={name} onChange={(e) => setName(e.target.value)} required />
              </label>
              <label>
                E-posta:
                <input type="email" name="email" value={email} onChange={(e) => setEmail(e.target.value)} required />
              </label>
              <label>
                Konu:
                <input type="text" name="subject" value={subject} onChange={(e) => setSubject(e.target.value)} required />
              </label>
              <label>
                Mesaj:
                <textarea name="message" rows="5" value={message} onChange={(e) => setMessage(e.target.value)} required></textarea>
              </label>
              <button type="submit">Mesajı Gönder</button>
            </form>
            {error && <div className="error">{error}</div>}
            {success && <div className="success">{success}</div>}
          </div>
        </div>
      </div>
    </>
  );
}

export default Contact;
